 if(action==='assign-random'){if(!allowedToEditTeamAssignment())throw Error('Teameinteilung ist gesperrt.');const names=(session.showSnapshot.settings.participantNames||[]).slice().sort(()=>Math.random()-.5);if(session.showSnapshot.teams.every(t=>t.kind==='individual')&&names.length>session.showSnapshot.teams.length)throw Error('Es gibt mehr Personen als Einzelspieler-Plätze. Bitte Team-Parteien hinzufügen.');return await mutate(()=>{session.teamAssignments={};names.forEach(n=>session.teamAssignments[n]=leastPopulatedTeam());});}
 if(action==='assign-person'){if(!allowedToEditTeamAssignment())throw Error('Teameinteilung ist gesperrt.');const name=decodeURIComponent(el.dataset.person),teamId=getInput('assign-team-'+el.dataset.index);const target=session.showSnapshot.teams.find(t=>t.id===teamId);if(!target)throw Error('Ungültiges Team.');if(target.kind==='individual'&&Object.values(session.teamAssignments).includes(teamId))throw Error('Ein Einzelspieler-Platz kann nur einer Person zugeordnet werden.');return await mutate(()=>{session.teamAssignments[name]=teamId;});}
