 if(action==='tie-score'){const g=activeGame(),real=Number(getInput('tie-correct'));if(!g||g.allowDraw)return;const tied=tiedLeaders();if(tied.length<2)throw Error('Aktuell liegt kein Gleichstand an der Spitze vor.');const values=tied.map(t=>({id:t.id,raw:getInput('tie-'+t.id)}));if(values.some(x=>!x.raw.trim())||!Number.isFinite(real))throw Error('Bitte alle Schätzungen und den richtigen Wert ausfüllen.');const guess=values.map(x=>({id:x.id,delta:Math.abs(Number(x.raw)-real)})).sort((a,b)=>a.delta-b.delta);if(guess.length>1&&guess[0].delta===guess[1].delta)throw Error('Auch die Schätzfrage ist unentschieden. Bitte neue Schätzfrage verwenden.');return await finishGame(guess[0].id);}
