 if(action==='player-join'){const name=getInput('join-name').trim(),p=publicForView(),match=Object.entries(p?.teamAssignments||{}).find(([n])=>n.toLocaleLowerCase('de')===name.toLocaleLowerCase('de'));const teamId=p?.teamAssignmentMode==='off'?getInput('join-team'):match?.[1];if(!name)throw Error('Bitte Namen eingeben.');if(!teamId)throw Error('Du wurdest noch keinem Team zugeordnet. Namen und Auslosung prüfen.');playerId=await bridge.join(name,teamId);playerName=name;playerTeam=teamId;localStorage.setItem('showstudio:player:'+sessionId,JSON.stringify({name,teamId,playerId}));inform('Du bist dabei!');return render()}
 if(action==='player-buzz'){if(!playerId)throw Error('Bitte zuerst beitreten.');if(!publicForView()?.buzzOpen)return;const ok=await bridge.buzz(playerId,playerTeam,playerName);inform(ok?'⚡ Du hast zuerst gebuzzert!':'Jemand war schneller!');return;}
 if(action==='player-option'){if(!playerId||!publicForView()?.entryOpen)return;await bridge.answer(playerId,el.dataset.value,publicForView().questionToken,playerTeam);inform('Antwort gesendet: '+el.dataset.value);return;}
