const builderChanges={
 'show-name':(s,v)=>s.name=v.slice(0,100),'show-subtitle':(s,v)=>s.subtitle=v.slice(0,180),
 'score-mode':(s,v)=>s.settings.scoreMode=v,'coins-mode':(s,v)=>s.settings.coinsEnabled=v==='yes','participants-mode':(s,v)=>s.settings.participants=v,
 'team-assignment':(s,v)=>s.settings.teamAssignment=v,'participant-names':(s,v)=>s.settings.participantNames=[...new Set(v.split('\n').map(x=>x.trim()).filter(Boolean))].slice(0,120),
 'draw-questions':(s,v)=>s.settings.drawQuestions=v.split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length>=3).slice(0,100).map(([category,text,...a])=>({category,text,answer:a.join(' | ')})),
 'default-seconds':(s,v)=>s.settings.defaultSeconds=toInt(v,0,3600),'default-buzz-delay':(s,v)=>s.settings.defaultBuzzDelaySeconds=toInt(v,0,300),'transition-mode':(s,v)=>s.settings.transition=v,
 'game-title':(s,v,g)=>g.title=v.slice(0,100),'game-description':(s,v,g)=>g.description=v.slice(0,500),
 'game-type':(s,v,g)=>g.type=v,'game-scoremode':(s,v,g)=>g.scoreMode=v,'game-answer':(s,v,g)=>g.answerMode=v,
 'game-winpoints':(s,v,g)=>g.winPoints=toInt(v,0,9999),'game-correct':(s,v,g)=>g.correctPoints=toInt(v,0,9999),'game-wrong':(s,v,g)=>g.wrongPoints=toInt(v,0,9999),
 'game-coin-correct':(s,v,g)=>g.coinCorrect=toInt(v,0,9999),'game-coin-win':(s,v,g)=>g.coinWin=toInt(v,0,9999),
 'game-seconds':(s,v,g)=>g.seconds=v===''?null:toInt(v,0,3600),
 'game-finishmode':(s,v,g)=>g.finishMode=v,'game-target':(s,v,g)=>g.target=toInt(v,1,100000),'game-duration':(s,v,g)=>g.gameDurationSeconds=toInt(v,0,21600),
 'game-draw-allowed':(s,v,g)=>g.allowDraw=v==='yes','game-buzz-delay':(s,v,g)=>g.buzzDelaySeconds=v===''?null:toInt(v,0,300),
 'game-autotimer':(s,v,g)=>g.autoTimer=v==='yes','game-autoopen':(s,v,g)=>g.autoOpen=v==='yes','game-secret-count':(s,v,g)=>g.secretCount=toInt(v,1,100),'game-secret-categories':(s,v,g)=>g.secretCategories=v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,30),
 'game-coin-recipient':(s,v,g)=>g.coinRecipient=v,'game-final':(s,v,g)=>g.isFinal=v==='yes','game-secret-pool':(s,v,g)=>g.secretPool=v==='yes',
 'game-tie-text':(s,v,g)=>g.tieBreakerText=v.slice(0,500),'game-tie-answer':(s,v,g)=>g.tieBreakerAnswer=Number(v)||0,'game-tolerance':(s,v,g)=>g.estimateTolerance=Math.max(.001,Number(v)||1),
 'game-wagerbonus':(s,v,g)=>g.wagerBonus=toInt(v,0,9999),'game-collections':(s,v,g)=>g.collectionNames=v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,24),
};
function handleChange(el){if(VIEW!=='host'||view!=='builder')return;const s=currentShow(),g=s.games.find(x=>x.id===editorGameId),id=el.id,v=el.type==='checkbox'?el.checked:el.value;if(builderChanges[id]){builderChanges[id](s,v,g);upsertShow(s);return renderPreserved();}
 if(id==='game-show-responses'){g.showResponses=!!v;upsertShow(s);return renderPreserved();}
 const tname=id.match(/^team-name-(.+)$/),tcolor=id.match(/^team-color-(.+)$/),tkind=id.match(/^team-kind-(.+)$/);if(tname||tcolor||tkind){const t=s.teams.find(t=>t.id===(tname||tcolor||tkind)[1]);if(!t)return;if(tname)t.name=v.slice(0,60);else if(tkind)t.kind=v;else t.color=v;upsertShow(s);return renderPreserved()}
 const qmatch=id.match(/^q-(text|answer|options|media-type|media|seconds|buzz-delay)-(.+)$/);if(qmatch){const q=g?.questions.find(x=>x.id===qmatch[2]);if(!q)return;const prop=qmatch[1];if(prop==='text')q.text=v;else if(prop==='answer')q.answer=v;else if(prop==='options')q.options=v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,6);else if(prop==='media-type')q.mediaType=v;else if(prop==='media')q.mediaUrl=safeUrl(v);else if(prop==='seconds')q.seconds=v===''?null:toInt(v,0,3600);else if(prop==='buzz-delay')q.buzzDelaySeconds=v===''?null:toInt(v,0,300);upsertShow(s);return renderPreserved()}}
function renderPreserved(){const y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo(0,y));}
root.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;handleAction(el);});
root.addEventListener('change',e=>handleChange(e.target));
root.addEventListener('input',e=>{const el=e.target;if(!el?.id)return;if(el.id==='join-name')playerDraftName=el.value;if(el.id==='moderator-answer')uiDraft['moderator-answer']=el.value;if(el.id==='player-answer')playerDraftAnswer=el.value;if(el.id.startsWith('estimate-')||el.id.startsWith('wager-')||el.id.startsWith('tie-'))uiDraft[el.id]=el.value;});
root.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='player-answer'){e.preventDefault();$('#app [data-act="player-send"]')?.click();}});
const fileInput=document.createElement('input');fileInput.id='import-json';fileInput.type='file';fileInput.accept='.json,application/json';fileInput.hidden=true;document.body.append(fileInput);
const poolInput=document.createElement('input');poolInput.id='pool-json';poolInput.type='file';poolInput.accept='.json,application/json';poolInput.hidden=true;document.body.append(poolInput);poolInput.addEventListener('change',async()=>{try{const f=poolInput.files?.[0];if(!f)return;const data=JSON.parse(await f.text()),rows=Array.isArray(data)?data:data?.questions;if(!Array.isArray(rows))throw Error('Die Datei benötigt ein Array von Fragen oder {questions:[…]}.');const add=rows.map(q=>({id:String(q.id||uid()),category:String(q.category||'Allgemeinwissen').slice(0,100),text:String(q.text||'').trim().slice(0,2000),answer:String(q.answer||'').trim().slice(0,1000),options:Array.isArray(q.options)?q.options.slice(0,6).map(String):[]})).filter(q=>q.text&&q.answer);if(!add.length)throw Error('Keine vollständigen Fragen gefunden.');const index=new Map(pool.map(q=>[q.text.toLocaleLowerCase('de'),q]));for(const q of add)index.set(q.text.toLocaleLowerCase('de'),q);pool=[...index.values()].slice(0,10000);localStorage.setItem('showstudio:v1:secret-pool',JSON.stringify(pool));inform(`${add.length} Fragen importiert · ${pool.length} insgesamt`);render();}catch(e){flashError(e)}finally{poolInput.value='';}});
fileInput.addEventListener('change',async()=>{if(!fileInput.files?.[0])return;try{await importFile(fileInput.files[0]);}catch(ex){flashError(ex)}fileInput.value='';});
async function initialize(){if(VIEW==='host'&&sessionId){view='host';try{if(sessionMode==='cloud'){view='login';lastAction='resume';}else await connectSession(sessionId,'local','host');}catch(ex){flashError(ex)}}
 else if(VIEW==='tv'||VIEW==='player'){
  const saved=getJSON('showstudio:player:'+sessionId,null);if(saved){playerId=saved.playerId;playerName=saved.name;playerTeam=saved.teamId;}
  if(sessionId){try{await connectSession(sessionId,sessionMode,VIEW)}catch(ex){flashError(ex)}}else error='Keine Show-ID übergeben.';
 }
 render();}
initialize();

// Beta 1.1: Countdowns live aktualisieren, ohne Eingabefelder neu zu zeichnen.
let ticking=false;
setInterval(async()=>{const p=publicForView();if(!p)return;const now=Date.now(),deadline=VIEW==='host'?session?.deadline:p.deadline,buzzAt=VIEW==='host'?session?.buzzUnlockAt:p.buzzUnlockAt;
 const display=deadline?Math.max(0,Math.ceil((deadline-now)/1000))+' s':'–';document.querySelectorAll('.timer-live').forEach(n=>n.textContent=display);
 const buzzRemaining=buzzAt?Math.max(0,Math.ceil((buzzAt-now)/1000)):0;document.querySelectorAll('.buzz-delay-live').forEach(n=>n.textContent=buzzRemaining?buzzRemaining+' s':'–');
 if(VIEW!=='host'||view!=='host'||!session||!bridge||ticking)return;
 if(session.phase==='game'&&session.published){
  if(session.buzzUnlockAt&&session.buzzUnlockAt<=now&&!session.buzzOpen&&!session.revealed){ticking=true;try{await mutate(()=>{session.buzzUnlockAt=0;session.buzzOpen=true;});}catch(e){console.warn(e);}finally{ticking=false;}return;}
  if(session.deadline&&session.deadline<=now&&!session.timerExpired){ticking=true;try{await mutate(()=>{session.deadline=0;session.timerExpired=true;session.buzzOpen=false;session.entryOpen=false;session.buzzUnlockAt=0;session.roundMessage='⏱ Antwortzeit abgelaufen';});}catch(e){console.warn(e);}finally{ticking=false;}}
 }
},350);
